function check(string $name, bool $ok, string $detail = ''): void {
    global $fail;
    echo ($ok ? 'OK  ' : 'FAIL ') . $name . ($detail !== '' ? ' :: ' . $detail : '') . "\n";
    if (!$ok) $fail++;
}
function throws(callable $fn): string {
    try { $fn(); return 'NONE'; }
    catch (Throwable $e) { return $e::class . ': ' . $e->getMessage(); }
}

